window.COURS = (window.COURS || []).concat([

/* ========= 7. LE VECTEUR VITESSE ET SA VARIATION ========= */
{
id:"vitesse", n:8, titre:"Le vecteur vitesse et sa variation",
sous:"Décrire un mouvement avec des flèches",
desc:"Référentiel, vecteur vitesse, construction sur une chronophotographie et variation du vecteur vitesse.",
duree:35,
sections:[
 {titre:"Aucun mouvement n'existe tout seul", blocs:[
  {t:"idee", x:"Un mouvement n'a de sens que **par rapport à quelque chose**. Ce quelque chose s'appelle le **référentiel**. Changer de référentiel change la description du mouvement — parfois du tout au tout."},
  {t:"p", x:"Assise dans un train, tu es immobile par rapport au wagon, et tu files à $300$ @u{km/h} par rapport aux rails. Les deux affirmations sont vraies en même temps : elles ne parlent simplement pas du même référentiel. C'est pour cela qu'un énoncé de physique commence toujours par préciser lequel il utilise."},
  {t:"tbl", head:["Référentiel","Ce à quoi il est lié","Quand l'utiliser"], rows:[
   ["Terrestre","Le sol","Presque tous les mouvements de la vie courante"],
   ["Géocentrique","Le centre de la Terre","Mouvement des satellites, de la Lune"],
   ["Héliocentrique","Le centre du Soleil","Mouvement des planètes"]
  ]},
  {t:"piege", titre:"« Immobile » n'est jamais une réponse complète", x:"Écrire « le sac est immobile » ne veut rien dire. Il faut écrire « le sac est immobile **dans le référentiel du train** ». Un correcteur attend cette précision, et elle vaut souvent un point."}
  ,{t:"mots", items:[
   ["Référentiel","L'objet par rapport auquel on décrit le mouvement. Sans lui, dire « ça bouge » n'a aucun sens."],
   ["Trajectoire","La ligne dessinée par les positions successives du mobile. Elle change avec le référentiel choisi."],
   ["Chronophotographie","Une suite de positions enregistrées à intervalles de temps **égaux**. Des points serrés = lent, des points espacés = rapide."],
   ["Vecteur","Une flèche qui porte trois informations à la fois : une direction, un sens et une longueur."],
   ["Tangente","La direction que suit la courbe à l'endroit exact où on la regarde. C'est celle du vecteur vitesse."],
   ["Célérité","Un autre mot pour la vitesse, réservé aux ondes. On l'emploie pour rappeler que rien ne se déplace vraiment."],
   ["Δ (delta)","Le symbole d'une **variation** : $Δv$ se lit « la variation de $v$ », c'est-à-dire la valeur d'arrivée moins celle de départ."]
  ]}
 ]},

 {titre:"Le vecteur vitesse : trois informations d'un coup", blocs:[
  {t:"idee", x:"La vitesse ne se résume pas à un nombre. Une voiture à $50$ @u{km/h} qui tourne et une voiture à $50$ @u{km/h} qui va tout droit n'ont pas le même mouvement. Il faut donc un **vecteur**, qui porte trois informations à la fois."},
  {t:"formule", titre:"Ce que contient le vecteur vitesse $@v{v}$",
   x:"**direction** : la tangente à la trajectoire<br>**sens** : celui du déplacement<br>**valeur** : $v = @f{d}{Δt}$, en @u{m/s}",
   note:"On note la valeur $v$ (sans flèche) et le vecteur $@v{v}$ (avec flèche). Les confondre coûte des points."},
  {t:"p", x:"La direction tangente mérite qu'on s'y arrête. Fais tourner une pierre au bout d'une ficelle, puis lâche : la pierre ne part ni vers le centre, ni en spirale. Elle part **droit devant**, dans la direction tangente au cercle à l'instant du lâcher. C'est la preuve la plus simple que le vecteur vitesse est tangent à la trajectoire."},
  {t:"formule", titre:"Conversion à connaître par cœur", x:"$1$ @u{m/s} $= 3{,}6$ @u{km/h}", note:"Pour passer des @u{km/h} aux @u{m/s}, on **divise** par 3,6. Dans l'autre sens, on multiplie."},
  {t:"exemple", titre:"Exemple guidé — passer d'une unité à l'autre", enonce:"Une voiture roule à $90$ @u{km/h}. Quelle est sa vitesse en @u{m/s} ? Un sprinteur court $100$ @u{m} en $10$ @u{s} : quelle est sa vitesse en @u{km/h} ?", etapes:[
   {q:"La voiture", r:"On passe des @u{km/h} aux @u{m/s} : on divise par $3{,}6$. $v = @f{90}{3{,}6} = 25$ @u{m/s}."},
   {q:"Le sprinteur, en @u{m/s}", r:"$v = @f{d}{Δt} = @f{100}{10} = 10$ @u{m/s}."},
   {q:"Le sprinteur, en @u{km/h}", r:"On multiplie par $3{,}6$ : $v = 10 × 3{,}6 = 36$ @u{km/h}."},
   {q:"Le contrôle de bon sens", r:"Un nombre en @u{km/h} est toujours **plus grand** que le même en @u{m/s}. Si ta conversion donne l'inverse, tu as multiplié au lieu de diviser."}
  ]}
 ]},

 {titre:"Construire le vecteur vitesse sur une chronophotographie", blocs:[
  {t:"p", x:"Une **chronophotographie** est une série de positions enregistrées à intervalles de temps égaux, notés $τ$ (tau). Les points sont d'autant plus espacés que le mobile va vite : la figure contient donc déjà toute l'information sur la vitesse, il ne reste qu'à la lire."},
  {t:"formule", titre:"Vitesse au point $M_i$",
   x:"$v_i ≈ @f{M_{i-1}M_{i+1}}{2τ}$",
   note:"On utilise les positions **encadrantes** : celle d'avant et celle d'après. C'est plus précis qu'un seul intervalle."},
  {t:"p", x:"Pourquoi encadrer plutôt que prendre le segment suivant ? Parce qu'on veut la vitesse **au point $M_i$**, pas entre $M_i$ et $M_{i+1}$. En prenant les deux voisins, le point d'intérêt se retrouve au milieu de l'intervalle de mesure : l'estimation est centrée, donc bien meilleure. Et comme on parcourt deux intervalles de temps, on divise par $2τ$ et non par $τ$."},
  {t:"fig", titre:"Lire une vitesse sur des positions successives",
   vue:[0,0,10,4], w:440, h:200, grille:false, axes:false,
   objets:[
    {t:"point", x:1, y:1.6, nom:"M₀", couleur:"ink3"},
    {t:"point", x:2.6, y:1.9, nom:"M₁", couleur:"ink3"},
    {t:"point", x:4.4, y:2.2, nom:"M₂", couleur:"ink"},
    {t:"point", x:6.4, y:2.5, nom:"M₃", couleur:"ink3"},
    {t:"point", x:8.6, y:2.8, nom:"M₄", couleur:"ink3"},
    {t:"seg", de:[2.6,1.9], a:[6.4,2.5], couleur:"line2", pointille:true},
    {t:"vec", de:[4.4,2.2], a:[6.3,2.5], couleur:"vert", nom:"v₂"},
    {t:"texte", x:4.5, y:0.9, txt:"on trace M₁M₃, on le reporte en M₂", couleur:"ink2", taille:12}
   ],
   note:"Les points s'écartent de plus en plus : le mobile accélère. Le vecteur vitesse en M₂ a la direction de M₁M₃."},
  {t:"exemple", titre:"Exemple guidé — calculer une vitesse ponctuelle", enonce:"Sur une chronophotographie prise toutes les $τ = 40$ @u{ms}, la distance $M_1M_3$ mesure $12$ @u{cm} en vraie grandeur. Quelle est la vitesse au point $M_2$ ?", etapes:[
   {q:"Convertir en unités du système", r:"$12$ @u{cm} $= 0{,}12$ @u{m} et $40$ @u{ms} $= 0{,}040$ @u{s}."},
   {q:"Écrire la formule", r:"$v_2 = @f{M_1M_3}{2τ}$."},
   {q:"Remplacer", r:"$v_2 = @f{0{,}12}{2 × 0{,}040} = @f{0{,}12}{0{,}080}$."},
   {q:"Calculer", r:"$v_2 = 1{,}5$ @u{m/s}, soit environ $5{,}4$ @u{km/h}."},
   {q:"L'erreur à ne pas faire", r:"Diviser par $τ$ au lieu de $2τ$ donnerait $3{,}0$ @u{m/s} : le double. La distance $M_1M_3$ a bien été parcourue en **deux** intervalles de temps."}
  ]},
  {t:"piege", titre:"L'échelle de la photo", x:"Sur une chronophotographie, les longueurs mesurées à la règle sont celles de l'image, pas de la réalité. L'énoncé donne toujours une **échelle** : $1$ @u{cm} sur la photo pour $10$ @u{cm} en réalité, par exemple. Oublier de l'appliquer fausse toutes les vitesses d'un même facteur."}
  ,{t:"figi", nom:"chronophoto"}
  ,{t:"p", x:"Déplace le point étudié : la flèche rouge encadre toujours ses deux voisins, et la flèche verte — le vecteur vitesse — s'allonge à mesure que le mobile accélère. Mets ensuite l'accélération à zéro : les points s'espacent régulièrement et la flèche verte garde la même longueur d'un bout à l'autre."}
  ,{t:"methode", titre:"Calculer une vitesse sur une chronophotographie", etapes:[
   "**Repérer le point demandé**, disons $M_2$, et ses deux voisins $M_1$ et $M_3$.",
   "**Mesurer la distance $M_1M_3$ à la règle**, puis la convertir en distance réelle avec l'échelle de la photo.",
   "**Convertir en unités du système** : les mètres pour la distance, les secondes pour $τ$ (attention, il est souvent donné en @u{ms}).",
   "**Diviser par $2τ$** et non par $τ$ : la distance couvre **deux** intervalles de temps.",
   "**Vérifier l'ordre de grandeur** : quelques @u{m/s} pour un objet lancé à la main, quelques dizaines pour un véhicule."
  ], exemple:"$M_1M_3 = 0{,}12$ @u{m} réels, $τ = 40$ @u{ms} $= 0{,}040$ @u{s}. Alors $v_2 = @f{0{,}12}{2 × 0{,}040} = 1{,}5$ @u{m/s}."}
 ]},

 {titre:"La variation du vecteur vitesse", blocs:[
  {t:"idee", x:"Ce qui intéresse vraiment le physicien, ce n'est pas la vitesse elle-même, mais **comment elle change**. Cette variation se note $Δ@v{v}$ et se construit en soustrayant deux vecteurs vitesse successifs."},
  {t:"formule", titre:"Variation du vecteur vitesse",
   x:"$Δ@v{v} = @v{v_{i+1}} - @v{v_i}$",
   note:"C'est une **soustraction de vecteurs**, pas de nombres. On la construit géométriquement."},
  {t:"p", x:"La construction se fait en trois gestes, toujours les mêmes."},
  {t:"liste", items:[
   "**1.** Reporter les deux vecteurs $@v{v_i}$ et $@v{v_{i+1}}$ à partir d'un **même point d'origine**.",
   "**2.** Tracer la flèche qui va de la pointe de $@v{v_i}$ à la pointe de $@v{v_{i+1}}$.",
   "**3.** Cette flèche est $Δ@v{v}$ : elle va bien de l'ancien vers le nouveau."
  ]},
  {t:"fig", titre:"La construction de la variation de vitesse",
   vue:[0,0,8,5], w:400, h:250, grille:false, axes:false,
   objets:[
    {t:"vec", de:[1.5,1], a:[5,1.8], couleur:"vert", nom:"vᵢ"},
    {t:"vec", de:[1.5,1], a:[4,3.8], couleur:"bleu", nom:"vᵢ₊₁"},
    {t:"vec", de:[5,1.8], a:[4,3.8], couleur:"rouge", nom:"Δv"},
    {t:"point", x:1.5, y:1, couleur:"ink"},
    {t:"texte", x:6.4, y:4.6, txt:"de la pointe de vᵢ", couleur:"ink3", taille:11.5},
    {t:"texte", x:6.4, y:4.1, txt:"vers celle de vᵢ₊₁", couleur:"ink3", taille:11.5}
   ],
   note:"Les deux vecteurs partent du même point. La flèche rouge les relie, dans le sens de la chronologie."},
  {t:"piege", titre:"Le sens de la flèche", x:"$Δ@v{v} = @v{v_{i+1}} - @v{v_i}$ va de la pointe de **l'ancien** vers la pointe du **nouveau**. Tracer la flèche dans l'autre sens donne un vecteur exactement opposé — et une conclusion inverse sur la force qui agit."}
  ,{t:"methode", titre:"Construire la variation du vecteur vitesse", etapes:[
   "**Tracer les deux vecteurs vitesse** $@v{v_i}$ et $@v{v_{i+1}}$ sur la figure, chacun à son point, tangents à la trajectoire.",
   "**Les reporter tous les deux à partir d'un même point** libre de la feuille, en gardant exactement leur direction et leur longueur.",
   "**Joindre les deux pointes** par une flèche allant de celle de $@v{v_i}$ vers celle de $@v{v_{i+1}}$ : c'est $Δ@v{v}$.",
   "**Lire sa direction**, et conclure : la somme des forces pointe dans cette direction, exactement."
  ], exemple:"Sur une trajectoire qui s'incurve vers le bas, les deux vecteurs vitesse penchent de plus en plus vers le sol : la flèche qui joint leurs pointes est dirigée vers le bas. C'est la signature du poids."},
  {t:"p", x:"Cette variation peut être non nulle même quand la **valeur** de la vitesse ne change pas. Sur un manège qui tourne à allure constante, la vitesse vaut toujours, disons, $3$ @u{m/s} — mais sa direction change en permanence. Le vecteur vitesse change donc, et $Δ@v{v}$ n'est pas nul : il pointe vers le centre du manège."}
 ]},

 {titre:"Ce que la variation raconte du mouvement", blocs:[
  {t:"tbl", head:["Mouvement","Le vecteur vitesse…","$Δ@v{v}$"], rows:[
   ["Rectiligne uniforme","garde direction, sens et valeur","**nul**"],
   ["Rectiligne accéléré","garde la direction, sa valeur augmente","dans le sens du mouvement"],
   ["Rectiligne ralenti","garde la direction, sa valeur diminue","dans le sens **opposé**"],
   ["Circulaire uniforme","garde sa valeur, change de direction","dirigé vers le **centre**"],
   ["Chute libre","change de valeur et de direction","dirigé vers le **bas**"]
  ]},
  {t:"idee", x:"Voici pourquoi tout cela compte : la direction de $Δ@v{v}$ est **exactement celle de la somme des forces**. En regardant seulement une trajectoire, on peut donc dire dans quel sens l'objet est tiré. C'est le pont vers le chapitre suivant."},
  {t:"figi", nom:"chute"},
  {t:"p", x:"La ligne du tableau qui résiste le plus est celle du mouvement circulaire : comment une vitesse qui ne change pas de valeur peut-elle quand même varier ? La figure suivante répond en le montrant. Fais tourner le point sur le cercle, puis regarde les deux flèches reportées en bas à gauche : elles ont **toujours la même longueur** — la valeur de la vitesse est bien constante — et pourtant la flèche rouge qui les relie n'est jamais nulle."},
  {t:"figi", nom:"circulaire"},
  {t:"p", x:"Réduis maintenant l'angle parcouru jusqu'à sa plus petite valeur : la flèche rouge devient perpendiculaire à la vitesse et pointe droit vers le **centre** du cercle. C'est le résultat à retenir, et il vaut pour la Lune autour de la Terre comme pour un seau qu'on fait tourner au bout d'une corde : ce qui les maintient sur leur cercle est une force dirigée vers l'intérieur."},
  {t:"p", x:"Sur cette figure, déplace les curseurs et observe : quelle que soit la vitesse de départ et l'angle choisi, le vecteur rouge — la variation de vitesse — pointe **toujours vers le bas**. Il ne change jamais de direction. C'est la signature du poids, la seule force en jeu."},
  {t:"check", q:"Une bille roule à vitesse constante sur un cercle horizontal. Que vaut $Δ@v{v}$ entre deux instants voisins ?",
   choix:["Un vecteur non nul, dirigé vers le centre du cercle","Le vecteur nul, puisque la vitesse ne change pas","Un vecteur tangent au cercle","Un vecteur dirigé vers l'extérieur"], bonne:0,
   expl:["Exact : la valeur de la vitesse ne change pas, mais sa direction, si. Le vecteur vitesse change donc, et sa variation pointe vers l'intérieur du cercle.",
         "Attention : c'est la **valeur** qui ne change pas. Le vecteur, lui, change de direction à chaque instant — il reste tangent à un cercle, donc il tourne.",
         "Le vecteur **vitesse** est tangent au cercle. Sa **variation**, elle, est perpendiculaire à la vitesse et rentre vers le centre.",
         "Vers l'extérieur, la bille s'éloignerait du centre et quitterait le cercle. C'est le contraire qui se produit : quelque chose la ramène vers l'intérieur — la ficelle, le rail ou le frottement."]}
 ]},

 {titre:"Récapitulatif", blocs:[
  {t:"liste", items:[
   "**1.** Préciser le référentiel avant toute description.",
   "**2.** Le vecteur vitesse est **tangent** à la trajectoire, orienté dans le sens du mouvement.",
   "**3.** Sur une chronophotographie : $v_i = @f{M_{i-1}M_{i+1}}{2τ}$, sans oublier l'échelle ni le facteur 2.",
   "**4.** $Δ@v{v}$ se construit de la pointe de l'ancien vecteur vers la pointe du nouveau.",
   "**5.** La direction de $Δ@v{v}$ est celle de la somme des forces : c'est ce qui rend cette construction si utile."
  ]},
  {t:"piege", titre:"Les erreurs les plus coûteuses", x:"**1.** Diviser par $τ$ au lieu de $2τ$ : la vitesse trouvée est doublée.<br>**2.** Oublier l'échelle de la chronophotographie.<br>**3.** Croire que $Δ@v{v}$ est nul dès que la valeur de la vitesse est constante — faux dans tout mouvement circulaire."}
 ]}
],
exos:[
 {id:"vi1", niveau:1, type:"num", enonce:"Une voiture roule à $108$ @u{km/h}. Quelle est sa vitesse en @u{m/s} ?",
  rep:30, tol:0.1, unite:"m/s",
  diag:[{v:388.8, m:"Tu as multiplié par $3{,}6$ au lieu de diviser. Un nombre en @u{km/h} est toujours plus grand que le même en @u{m/s} : la conversion doit donc **réduire** le nombre."},
        {v:1.8, m:"Tu as divisé par $60$, comme pour passer des heures aux minutes. Le facteur entre @u{km/h} et @u{m/s} est $3{,}6$ : il combine les $1000$ mètres du kilomètre et les $3600$ secondes de l'heure."},
        {v:10.8, m:"Tu as divisé par $10$. Le bon facteur est $3{,}6$."}],
  corr:["**Ce que dit l'énoncé.** Une vitesse de $108$ @u{km/h}. On la veut en @u{m/s}.",
        "**D'où vient le facteur $3{,}6$ ?** Un kilomètre vaut $1000$ mètres, une heure vaut $3600$ secondes. Passer des @u{km/h} aux @u{m/s} revient donc à multiplier par $@f{1000}{3600}$, c'est-à-dire à diviser par $3{,}6$.",
        "**Dans quel sens diviser ?** Un même mouvement donne toujours un **grand** nombre en @u{km/h} et un **petit** en @u{m/s}. Ici on va vers les @u{m/s} : le nombre doit diminuer, donc on divise.",
        "**Je pose le calcul.** $v = @f{108}{3{,}6}$.",
        "**Je calcule.** $108 ÷ 3{,}6 = 30$. Donc $v = 30$ @u{m/s}.",
        "**Je vérifie en sens inverse.** $30 × 3{,}6 = 108$ : je retombe sur la valeur de départ. Le résultat est bon."],
  indice:"$1$ @u{m/s} vaut $3{,}6$ @u{km/h} : la conversion vers les @u{m/s} donne un nombre plus petit."},

 {id:"vi2", niveau:1, type:"qcm", enonce:"Quelle est la direction du vecteur vitesse d'un point en mouvement ?",
  choix:["La tangente à la trajectoire","La perpendiculaire à la trajectoire","La droite qui joint le point au centre","Toujours l'horizontale"], bonne:0,
  diag:["",
        "La perpendiculaire à la trajectoire est la direction de la **variation** de vitesse dans un mouvement circulaire, pas celle de la vitesse elle-même.",
        "C'est la direction du rayon dans un mouvement circulaire. La vitesse, elle, lui est perpendiculaire.",
        "Un objet qui tombe a une vitesse verticale. La direction dépend du mouvement, pas d'une orientation fixe."],
  corr:["**Ce que demande la question.** La direction du vecteur vitesse d'un point en mouvement.",
        "**Ce que représente ce vecteur.** Il indique où va le point **à l'instant considéré**, et à quelle allure.",
        "**Sur une trajectoire courbe.** Cette direction change en permanence : à chaque instant, elle suit la courbe là où le point se trouve.",
        "**Comment s'appelle cette direction ?** Celle qui épouse la courbe en un point est la **tangente** à la trajectoire.",
        "**L'expérience qui le prouve.** Fais tourner une pierre au bout d'une ficelle, puis lâche. Elle ne part ni vers le centre, ni en spirale : elle part droit devant, selon la tangente au cercle à l'instant du lâcher.",
        "**Je conclus.** Le vecteur vitesse est **tangent à la trajectoire**, orienté dans le sens du mouvement."],
  indice:"Pense à une pierre qu'on lâche au bout d'une ficelle qu'on faisait tourner."},

 {id:"vi3", niveau:2, type:"num", enonce:"Sur une chronophotographie prise toutes les $τ = 50$ @u{ms}, la distance réelle $M_1M_3$ vaut $0{,}20$ @u{m}. Quelle est la vitesse au point $M_2$, en @u{m/s} ?",
  rep:2, tol:0.02, unite:"m/s",
  diag:[{v:4, m:"Tu as divisé par $τ$ au lieu de $2τ$. La distance $M_1M_3$ est parcourue en **deux** intervalles de temps, puisqu'elle enjambe $M_2$."},
        {v:0.5, m:"Tu as inversé la fraction : tu as calculé $@f{2τ}{d}$. La vitesse est une distance divisée par une durée."},
        {v:0.002, m:"Tu as gardé la durée en millisecondes tout en divisant comme si c'étaient des secondes. $50$ @u{ms} $= 0{,}050$ @u{s}."}],
  corr:["**Ce que dit l'énoncé.** Une chronophotographie prise toutes les $τ = 50$ @u{ms}, et une distance réelle $M_1M_3 = 0{,}20$ @u{m}. On cherche la vitesse **au point $M_2$**.",
        "**Pourquoi on encadre le point.** On veut la vitesse en $M_2$, pas entre deux positions. En prenant $M_1$ et $M_3$, le point d'intérêt se retrouve au **milieu** de l'intervalle de mesure : l'estimation est centrée, donc bien meilleure.",
        "**D'où vient le $2$ de la formule.** De $M_1$ à $M_3$, il s'écoule **deux** intervalles de temps : d'abord $M_1$ à $M_2$, puis $M_2$ à $M_3$. La durée totale est donc $2τ$, et la formule s'écrit $v_2 = @f{M_1M_3}{2τ}$.",
        "**Je convertis la durée.** $τ = 50$ @u{ms} $= 0{,}050$ @u{s}, donc $2τ = 0{,}10$ @u{s}.",
        "**Je remplace et je calcule.** $v_2 = @f{0{,}20}{0{,}10} = 2{,}0$ @u{m/s}.",
        "**Je vérifie l'ordre de grandeur.** $2$ @u{m/s} font environ $7$ @u{km/h} : l'allure d'un objet lancé à la main. Cohérent. Diviser par $τ$ au lieu de $2τ$ aurait donné le double, $4{,}0$ @u{m/s}."],
  indice:"Entre $M_1$ et $M_3$, il s'est écoulé deux intervalles de temps, pas un."},

 {id:"vi4", niveau:2, type:"qcm", enonce:"Un objet a un mouvement rectiligne uniforme. Que vaut la variation de son vecteur vitesse entre deux instants ?",
  choix:["Le vecteur nul","Un vecteur dirigé vers l'avant","Un vecteur dirigé vers le bas","Un vecteur perpendiculaire au mouvement"], bonne:0,
  diag:["",
        "Ce serait le cas d'un mouvement **accéléré**. « Uniforme » signifie justement que la valeur de la vitesse ne change pas.",
        "Un $Δ@v{v}$ vers le bas caractérise une chute libre, où la vitesse change à cause du poids. Ici rien ne change.",
        "Une variation perpendiculaire au mouvement caractérise une trajectoire qui **tourne**. Ici la trajectoire est rectiligne."],
  corr:["**Ce que dit l'énoncé.** Le mouvement est **rectiligne uniforme**. On cherche la variation du vecteur vitesse.",
        "**Je décompose les deux mots.** « Rectiligne » parle de la **direction** : la trajectoire est une droite, donc la direction ne change pas. « Uniforme » parle de la **valeur** : la vitesse ne ralentit ni n'accélère.",
        "**Ce qui reste du vecteur.** Direction constante, sens constant, valeur constante : les trois informations que porte le vecteur vitesse sont inchangées.",
        "**J'en déduis.** Le vecteur vitesse est rigoureusement le même d'un instant à l'autre : $@v{v_{i+1}} = @v{v_i}$.",
        "**Je calcule la variation.** $Δ@v{v} = @v{v_{i+1}} - @v{v_i} = @v{0}$. C'est le vecteur nul.",
        "**Ce que cela m'apprend en plus.** Puisque $Δ@v{v}$ donne la direction de la somme des forces, celle-ci est nulle aussi : c'est le principe d'inertie."],
  indice:"Décompose le mot : « rectiligne » parle de la direction, « uniforme » de la valeur."},

 {id:"vi5", niveau:2, type:"num", enonce:"Un cycliste parcourt $450$ @u{m} en $30$ @u{s}. Quelle est sa vitesse moyenne en @u{km/h} ?",
  rep:54, tol:0.5, unite:"km/h",
  diag:[{v:15, m:"$15$ @u{m/s} est le bon résultat, mais dans la mauvaise unité. La question demande des @u{km/h} : il reste à multiplier par $3{,}6$."},
        {v:4.17, m:"Tu as divisé par $3{,}6$ au lieu de multiplier. On part de @u{m/s} pour aller vers les @u{km/h} : le nombre doit **augmenter**."},
        {v:0.067, m:"Tu as calculé $@f{Δt}{d}$. La vitesse est une distance divisée par une durée."}],
  corr:["**Ce que dit l'énoncé.** $450$ @u{m} parcourus en $30$ @u{s}. La réponse est attendue en @u{km/h}.",
        "**Le plan.** Je calcule d'abord la vitesse dans les unités des données (@u{m} et @u{s}), et je convertis ensuite. Mélanger les deux opérations est la meilleure façon de se tromper.",
        "**Étape 1 — la vitesse moyenne.** $v = @f{d}{Δt} = @f{450}{30}$.",
        "**Je calcule.** $v = 15$ @u{m/s}.",
        "**Étape 2 — la conversion.** On va des @u{m/s} vers les @u{km/h} : le nombre doit **augmenter**, donc on multiplie par $3{,}6$. $v = 15 × 3{,}6$.",
        "**Je calcule et je vérifie.** $v = 54$ @u{km/h}. C'est une allure de cycliste rapide : plausible. Si j'avais divisé, j'aurais trouvé $4{,}2$ @u{km/h}, une allure de marche — invraisemblable pour $450$ @u{m} en $30$ @u{s}."],
  indice:"Calcule d'abord en @u{m/s}, puis convertis."},

 {id:"vi6", niveau:3, type:"qcm", enonce:"Une bille tourne à vitesse constante sur un cercle. Vers où pointe la variation de son vecteur vitesse ?",
  choix:["Vers le centre du cercle","Dans le sens du mouvement","Vers l'extérieur du cercle","Elle est nulle"], bonne:0,
  diag:["",
        "Dans le sens du mouvement, la bille irait de plus en plus vite. Or sa vitesse garde la même valeur.",
        "Vers l'extérieur, la bille s'éloignerait et quitterait le cercle. C'est l'inverse qui la maintient sur sa trajectoire.",
        "Ce serait vrai si le vecteur vitesse ne changeait pas du tout. Mais sa **direction** change en permanence, même si sa valeur reste la même."],
  corr:["**Ce que dit l'énoncé.** Une bille tourne à **vitesse constante** sur un cercle. On cherche la direction de $Δ@v{v}$.",
        "**Le piège.** « Vitesse constante » ne veut dire que **valeur** constante. Le vecteur, lui, comporte aussi une direction — et sur un cercle, cette direction tourne sans arrêt.",
        "**Étape 1 — je place les deux vecteurs.** À deux instants voisins, chacun est tangent au cercle, de même longueur, mais légèrement pivoté l'un par rapport à l'autre.",
        "**Étape 2 — je les reporte à partir d'un même point.** Deux flèches de même longueur, formant un petit angle entre elles.",
        "**Étape 3 — je joins les pointes**, de l'ancienne vers la nouvelle. La flèche obtenue est presque perpendiculaire aux deux, et pointe **vers l'intérieur** du cercle.",
        "**Je conclus, et j'en tire le sens physique.** $Δ@v{v}$ est dirigé vers le centre. Donc la somme des forces l'est aussi : c'est la ficelle, le rail ou le frottement qui retient la bille et l'empêche de partir tout droit."],
  indice:"Construis les deux vecteurs vitesse à partir d'un même point et regarde vers où pointe la flèche qui les relie."},

 {id:"vi7", niveau:3, type:"num", enonce:"Un mobile passe de $v_1 = 4{,}0$ @u{m/s} à $v_2 = 10{,}0$ @u{m/s} en ligne droite, en $2{,}0$ @u{s}. Quelle est la valeur de la variation de vitesse par seconde, en @u{m/s²} ?",
  rep:3, tol:0.05, unite:"m/s²",
  diag:[{v:6, m:"$6{,}0$ @u{m/s} est la variation **totale** de vitesse. La question demande la variation **par seconde** : il reste à diviser par la durée."},
        {v:7, m:"Tu as calculé la moyenne des deux vitesses. La variation est une différence, pas une moyenne."},
        {v:0.33, m:"Tu as inversé la fraction : $@f{Δt}{Δv}$. La variation par seconde est $@f{Δv}{Δt}$."}],
  corr:["**Ce que dit l'énoncé.** La vitesse passe de $4{,}0$ à $10{,}0$ @u{m/s} en $2{,}0$ @u{s}, en ligne droite. On cherche la variation **par seconde**.",
        "**Pourquoi je peux travailler sur les valeurs.** Le mouvement est rectiligne : la direction ne change pas, seule la valeur évolue. Pas besoin de construction géométrique ici.",
        "**Étape 1 — la variation totale.** $Δv = v_{final} - v_{initial} = 10{,}0 - 4{,}0 = 6{,}0$ @u{m/s}. C'est ce que la vitesse a gagné en tout.",
        "**Étape 2 — ramener à une seconde.** Ces $6{,}0$ @u{m/s} ont été gagnés en $2{,}0$ @u{s}. Par seconde, cela fait $@f{6{,}0}{2{,}0}$.",
        "**Je calcule.** $3{,}0$ @u{m/s²}. La vitesse augmente de $3$ @u{m/s} chaque seconde.",
        "**Je vérifie.** Après $1$ seconde : $4 + 3 = 7$ @u{m/s}. Après $2$ secondes : $7 + 3 = 10$ @u{m/s}. C'est bien la vitesse finale annoncée."],
  indice:"D'abord la variation totale, ensuite la division par la durée."},

 {id:"vi8", niveau:3, type:"txt", enonce:"Dans quel référentiel un passager assis dans un train en marche est-il immobile ? (un mot)",
  reps:["le train","train","referentiel du train","celui du train","wagon"],
  diag:[{r:"terrestre", m:"Dans le référentiel terrestre, lié au sol, le passager défile à la vitesse du train : il n'y est pas immobile du tout. Cherche le référentiel qui bouge **avec** lui."},
        {r:"sol", m:"Par rapport au sol, le passager avance à la vitesse du train. Le référentiel où il est immobile est celui qui l'accompagne."}],
  corr:["**Ce que demande la question.** Dans quel référentiel un passager assis dans un train en marche est immobile.",
        "**Ce que veut dire « immobile ».** Un objet est immobile dans un référentiel si sa **position n'y change pas** au fil du temps. Sans référentiel précisé, le mot ne veut rien dire.",
        "**Je teste le référentiel terrestre.** Il est lié au sol, aux rails, au paysage. Par rapport à eux, le passager défile à la vitesse du train : il n'y est pas immobile.",
        "**Je teste le référentiel du train.** Il est lié au wagon, qui se déplace avec le passager. Par rapport à son siège, à la table, à la fenêtre, sa position ne change pas.",
        "**Je conclus.** Il est immobile dans le **référentiel du train** — et en mouvement dans le référentiel terrestre.",
        "**Ce qu'il faut retenir.** Les deux affirmations sont vraies **en même temps**. Elles ne se contredisent pas : elles ne parlent simplement pas du même référentiel."],
  indice:"Cherche le référentiel qui se déplace en même temps que lui."},

{id:"vi9", niveau:1, type:"num", enonce:"Un TGV file à $324$ @u{km/h}. Quelle distance parcourt-il en une seule seconde, en mètres ?",
  rep:90, tol:0.5, unite:"m",
  diag:[{v:324, m:"$324$ est la distance parcourue en une **heure**, et en kilomètres. La question porte sur une seconde."},
        {v:1166, m:"Tu as multiplié par $3{,}6$ au lieu de diviser. Vers les @u{m/s}, le nombre doit diminuer."},
        {v:5.4, m:"Tu as divisé par $60$, comme pour passer des heures aux minutes. Le facteur entre @u{km/h} et @u{m/s} est $3{,}6$."}],
  corr:["**Ce que dit l'énoncé.** Une vitesse en @u{km/h}. Ce qu'on cherche : une distance en mètres, parcourue en une seconde.",
        "**Le lien entre les deux.** Une vitesse en @u{m/s} est justement le nombre de mètres parcourus **par seconde**. Convertir la vitesse suffit donc à répondre.",
        "**Le facteur de conversion.** $1$ @u{m/s} $= 3{,}6$ @u{km/h}. Pour aller vers les @u{m/s}, on divise par $3{,}6$.",
        "**Je calcule.** $v = @f{324}{3{,}6} = 90$ @u{m/s}.",
        "**Je réponds à la question posée.** En une seconde, le train parcourt donc $90$ @u{m} — la longueur d'un terrain de football.",
        "**Je vérifie.** $90 × 3{,}6 = 324$ : je retombe sur la valeur de départ."],
  indice:"Une vitesse en @u{m/s}, c'est exactement le nombre de mètres parcourus en une seconde."},

 {id:"vi10", niveau:2, type:"num", enonce:"Sur une chronophotographie prise toutes les $τ = 25$ @u{ms}, la distance $M_1M_3$ mesure $3{,}0$ @u{cm} **sur la photo**. L'échelle est : $1$ @u{cm} sur la photo pour $10$ @u{cm} en réalité. Quelle est la vitesse au point $M_2$, en @u{m/s} ?",
  rep:6, tol:0.05, unite:"m/s",
  diag:[{v:0.6, m:"Tu as oublié d'appliquer l'échelle : $3{,}0$ @u{cm} sur la photo valent $30$ @u{cm} en réalité, soit dix fois plus. Ton résultat est dix fois trop petit."},
        {v:12, m:"Tu as divisé par $τ$ au lieu de $2τ$. La distance $M_1M_3$ enjambe le point $M_2$ : elle couvre **deux** intervalles de temps."},
        {v:3, m:"Tu as divisé par $4τ$, ou appliqué deux fois une division par 2. Il n'y a qu'un seul facteur 2 à placer."}],
  corr:["**Ce que dit l'énoncé.** Une longueur mesurée à la règle **sur la photo**, une échelle, et l'intervalle de temps entre deux positions.",
        "**Le piège de l'échelle.** Ce qu'on mesure à la règle n'est pas la distance réelle. L'échelle dit que chaque centimètre de photo vaut $10$ @u{cm} en vrai.",
        "**Je convertis en distance réelle.** $3{,}0$ @u{cm} $× 10 = 30$ @u{cm}, soit $0{,}30$ @u{m}.",
        "**Je convertis la durée.** $τ = 25$ @u{ms} $= 0{,}025$ @u{s}, donc $2τ = 0{,}050$ @u{s}.",
        "**J'applique la formule.** $v_2 = @f{M_1M_3}{2τ} = @f{0{,}30}{0{,}050}$.",
        "**Je calcule et je vérifie.** $v_2 = 6{,}0$ @u{m/s}, soit environ $22$ @u{km/h} : l'allure d'un objet lancé. Cohérent."],
  indice:"Trois étapes dans cet ordre : appliquer l'échelle, convertir la durée, puis diviser par $2τ$."},

 {id:"vi11", niveau:2, type:"qcm", enonce:"Une voiture roule en ligne droite et **freine**. Vers où pointe la variation de son vecteur vitesse $Δ@v{v}$ ?",
  choix:["Vers l'arrière, en sens opposé au mouvement","Vers l'avant, dans le sens du mouvement",
         "Elle est nulle","Perpendiculairement à la route"], bonne:0,
  diag:["",
        "Une variation vers l'avant ferait **accélérer** la voiture. Or elle freine : sa vitesse diminue.",
        "Une variation nulle signifierait une vitesse constante. Freiner, c'est justement faire varier la vitesse.",
        "Une variation perpendiculaire au mouvement fait **tourner** la trajectoire. Ici la voiture va tout droit."],
  corr:["**Ce que dit l'énoncé.** Trajectoire rectiligne, et vitesse qui **diminue**.",
        "**Je construis les deux vecteurs.** Ils ont la même direction et le même sens — la route est droite — mais le second est plus **court** que le premier.",
        "**Je les reporte à partir d'un même point.** Deux flèches alignées, l'une plus courte que l'autre.",
        "**Je joins les pointes**, de l'ancienne vers la nouvelle. Comme la nouvelle est plus courte, cette flèche pointe **vers l'arrière**.",
        "**Je conclus.** $Δ@v{v}$ est opposée au mouvement.",
        "**Ce que cela m'apprend sur les forces.** La somme des forces pointe dans la même direction : vers l'arrière. Ce sont les freins et les frottements — et c'est bien ce qui ralentit la voiture."],
  indice:"Les deux vecteurs sont alignés, mais le second est plus court. De quel côté va la flèche qui joint leurs pointes ?"},

 {id:"vi12", niveau:3, type:"num", enonce:"Un coureur parcourt $100$ @u{m} à $5{,}0$ @u{m/s}, puis $100$ @u{m} à $10{,}0$ @u{m/s}. Quelle est sa vitesse **moyenne** sur les $200$ @u{m}, en @u{m/s} ? (arrondis au dixième)",
  rep:6.7, tol:0.1, unite:"m/s",
  diag:[{v:7.5, m:"Tu as fait la moyenne des deux vitesses. C'est le piège de cet exercice : la vitesse moyenne n'est **pas** la moyenne des vitesses. Le coureur passe deux fois plus de temps sur la portion lente, qui pèse donc deux fois plus lourd."},
        {v:15, m:"Tu as additionné les deux vitesses. Une vitesse moyenne se calcule toujours par $@f{distance totale}{durée totale}$."},
        {v:5, m:"Tu as gardé la vitesse de la première portion. La moyenne doit être comprise entre $5$ et $10$."}],
  corr:["**La seule définition valable.** Vitesse moyenne $= @f{distance totale}{durée totale}$. Tout part de là — surtout pas d'une moyenne des vitesses.",
        "**La durée de la première portion.** $Δt_1 = @f{d}{v} = @f{100}{5{,}0} = 20$ @u{s}.",
        "**La durée de la seconde.** $Δt_2 = @f{100}{10{,}0} = 10$ @u{s}. Deux fois plus courte : il va deux fois plus vite.",
        "**La durée totale.** $20 + 10 = 30$ @u{s}, pour $200$ @u{m} parcourus.",
        "**Je calcule.** $v_{moy} = @f{200}{30} ≈ 6{,}7$ @u{m/s}.",
        "**Pourquoi ce n'est pas $7{,}5$.** Le coureur passe **deux fois plus de temps** à $5$ @u{m/s} qu'à $10$ @u{m/s} : la portion lente pèse deux fois plus dans la moyenne, qui penche donc vers le bas."],
  indice:"Calcule les deux durées séparément, puis divise la distance totale par la durée totale."},

{id:"vi13", niveau:2, type:"num", unite:"m/s",
  enonce:"Le graphique ci-dessous donne la position d'un mobile en fonction du temps. Quelle est sa vitesse entre $0$ et $4{,}0$ @u{s} ?",
  fig:{titre:"Document — position en fonction du temps", vue:[0,0,6.5,26], w:400, h:250,
       libre:true, grille:false, axes:false, objets:[
    {t:"axes", x0:0, y0:0, ax:"t (s)", ay:"x (m)"},
    {t:"courbeXY", pts:[[0,0],[4,20],[6,20]], couleur:"bleu", points:true},
    {t:"seg", de:[4,0], a:[4,20], couleur:"line2", pointille:true},
    {t:"seg", de:[0,20], a:[4,20], couleur:"line2", pointille:true},
    {t:"texte", x:4.3, y:1.6, txt:"4,0 s", couleur:"ink3", taille:11.5},
    {t:"texte", x:0.75, y:21.6, txt:"20 m", couleur:"ink3", taille:11.5}
   ], note:"Après 4 s, la courbe devient horizontale : le mobile s'est arrêté."},
  rep:5, tol:0.1,
  diag:[{v:20, m:"$20$ @u{m} est la **distance** parcourue, lue sur l'axe vertical. La vitesse est cette distance divisée par la durée."},
        {v:80, m:"Tu as multiplié la distance par la durée. Une vitesse est un quotient : des mètres divisés par des secondes."},
        {v:0.2, m:"Tu as inversé la fraction ($@f{4{,}0}{20}$). Vérifie par les unités : des mètres divisés par des secondes donnent des @u{m/s}."}],
  corr:["**Je lis le document avant tout.** L'axe horizontal porte le temps en secondes, l'axe vertical la position en mètres.",
        "**Je repère les deux points utiles.** À $t = 0$, la position vaut $0$ @u{m}. À $t = 4{,}0$ @u{s}, elle vaut $20$ @u{m}.",
        "**J'en tire la distance parcourue.** $20 - 0 = 20$ @u{m}, en $4{,}0$ @u{s}.",
        "**J'applique la définition.** $v = @f{d}{Δt} = @f{20}{4{,}0}$.",
        "**Je calcule.** $v = 5{,}0$ @u{m/s}, soit $18$ @u{km/h}.",
        "**Je lis la suite du graphique.** Après $4$ @u{s}, la courbe devient **horizontale** : la position ne change plus, le mobile est à l'arrêt. La pente d'un graphique position-temps, c'est exactement la vitesse."],
  indice:"Lis la position au début et à la fin, puis divise l'écart par la durée."}
]
},

/* ======= 8. FORCES ET DEUXIÈME LOI DE NEWTON ======= */
{
id:"forces", n:9, titre:"Forces et lois de Newton",
sous:"Ce qui met en mouvement, ce qui freine, ce qui fait tourner",
desc:"Modéliser une action par une force, principe d'inertie, deuxième loi de Newton, gravitation et interaction électrostatique.",
duree:40,
sections:[
 {titre:"Une force modélise une interaction", blocs:[
  {t:"idee", x:"Une **force** n'est jamais une propriété d'un objet : c'est la façon dont un objet **agit sur un autre**. Il faut donc toujours deux acteurs, et une force se nomme en les citant tous les deux."},
  {t:"p", x:"On écrit $@v{F}_{Terre/pomme}$ et jamais « la force de la pomme ». Cette écriture n'est pas un caprice de notation : elle oblige à identifier qui agit sur qui, ce qui évite d'inventer des forces qui n'existent pas."},
  {t:"p", x:"Une force se représente par un vecteur, avec les mêmes trois informations que le vecteur vitesse : une direction, un sens, et une valeur en **newtons** (@u{N})."},
  {t:"tbl", head:["Force","Direction et sens","Valeur"], rows:[
   ["Poids $@v{P}$","Verticale, vers le bas","$P = m × g$"],
   ["Réaction du support $@v{R}$","Perpendiculaire au support","Selon la situation"],
   ["Tension d'un fil $@v{T}$","Selon le fil, vers le point d'attache","Selon la situation"],
   ["Frottement $@v{f}$","Selon le mouvement, en sens **opposé**","Selon la situation"]
  ]},
  {t:"formule", titre:"Le poids", x:"$P = m × g$", note:"$P$ en @u{N} · $m$ en @u{kg} · $g ≈ 9{,}81$ @u{N/kg} sur Terre. On prend souvent $10$ pour un calcul rapide."},
  {t:"piege", titre:"Masse et poids ne sont pas la même chose", x:"La **masse** est une quantité de matière : elle se mesure en @u{kg} et ne change jamais. Le **poids** est une force : il se mesure en @u{N} et dépend de l'astre. Une élève de $50$ @u{kg} pèse $490$ @u{N} sur Terre et $80$ @u{N} sur la Lune — mais sa masse reste $50$ @u{kg} partout."}
  ,{t:"mots", items:[
   ["Force","La façon dont un objet agit sur un autre. Elle se note toujours en citant les deux : $@v{F}_{Terre/pomme}$."],
   ["Newton (@u{N})","L'unité des forces. Un newton, c'est à peu près le poids d'une petite pomme."],
   ["Système","L'objet dont on parle, et lui seul. On le choisit au début de l'exercice, et on n'en change plus."],
   ["Bilan des forces","La liste complète de ce qui agit sur le système : d'abord les contacts, ensuite les forces à distance."],
   ["Force de contact","Elle exige un contact : la réaction d'un support, la tension d'un fil, un frottement."],
   ["Force à distance","Elle agit sans contact : le poids, la gravitation, l'attraction électrique."],
   ["Inertie","La tendance d'un objet à garder son mouvement tant que rien ne le change. C'est l'objet de la première loi de Newton."]
  ]},
  {t:"fig", titre:"Les forces sur un objet posé sur une table",
   vue:[0,0,8,6], w:340, h:250, grille:false, axes:false,
   objets:[
    {t:"sol", de:1, a:7, y:1.4},
    {t:"rect", x:3, y:1.4, w:2, h:1.2, couleur:"bleu", nom:"m"},
    {t:"vec", de:[4,2], a:[4,0.4], couleur:"rouge", nom:"P"},
    {t:"vec", de:[4,2], a:[4,4.4], couleur:"vert", nom:"R"},
    {t:"texte", x:6.4, y:4.2, txt:"R : la table pousse", couleur:"vert", taille:11.5},
    {t:"texte", x:6.3, y:0.7, txt:"P : la Terre attire", couleur:"rouge", taille:11.5}
   ],
   note:"Deux forces exactement opposées : leur somme est nulle, l'objet ne bouge pas."}
 ]},

 {titre:"Le principe d'inertie : rien ne change sans raison", blocs:[
  {t:"formule", titre:"Première loi de Newton",
   x:"Si $Σ@v{F} = @v{0}$, alors le vecteur vitesse **ne change pas**.<br>Et réciproquement.",
   note:"L'objet est soit immobile, soit en mouvement rectiligne uniforme. Les deux cas sont équivalents du point de vue des forces."},
  {t:"p", x:"Ce principe heurte l'intuition, et il a fallu deux mille ans pour l'admettre. Notre expérience quotidienne dit qu'il faut pousser pour qu'un objet continue d'avancer. Mais si l'objet ralentit dès qu'on cesse de pousser, ce n'est pas parce que le mouvement s'épuise : c'est parce que **les frottements agissent**. Sur une patinoire, où ils sont presque nuls, un palet lancé continue tout droit très longtemps."},
  {t:"astuce", titre:"La conséquence pratique", x:"Si tu constates qu'un objet va en ligne droite à vitesse constante, tu peux affirmer immédiatement que **la somme des forces est nulle**. Cela ne veut pas dire qu'il n'y a aucune force : cela veut dire qu'elles se compensent exactement, comme le poids et la réaction sur la table."}
  ,{t:"figi", nom:"bilan"}
  ,{t:"p", x:"Le poids et la réaction du sol se compensent en permanence — c'est pour cela que la caisse ne s'enfonce pas et ne décolle pas. Joue sur les deux forces horizontales : quand elles s'égalisent, la somme s'annule et le mouvement ne change plus, quelle que soit la vitesse déjà acquise."}
  ,{t:"methode", titre:"Faire le bilan des forces, sans en oublier", etapes:[
   "**Écrire le système étudié** en toutes lettres : « le système est la caisse ». Tout ce qui suit ne concerne qu'elle.",
   "**Chercher les contacts** : qu'est-ce qui touche le système ? Un support, un fil, l'air ? Chaque contact donne une force.",
   "**Ajouter les forces à distance** : sur Terre, il y a toujours le poids. Parfois une force électrique.",
   "**Dessiner chaque force par une flèche partant du centre de l'objet**, avec son nom.",
   "**Regarder si elles se compensent** : si oui, le vecteur vitesse ne change pas ; si non, il change dans la direction de leur somme."
  ], exemple:"Une caisse tirée sur le sol : contacts = le sol (réaction, et frottement), la corde (tension). À distance = le poids. Quatre forces, pas une de plus."},
  {t:"check", q:"Un parachutiste descend à vitesse constante. Que peut-on dire des forces qui s'exercent sur lui ?",
   choix:["Elles se compensent exactement","Seul le poids agit","La force de l'air est plus grande que le poids","Il n'y a aucune force"], bonne:0,
   expl:["Exact : vitesse constante et trajectoire rectiligne signifient $Σ@v{F} = @v{0}$. Le frottement de l'air compense exactement le poids.",
         "Si seul le poids agissait, il accélérerait sans cesse — c'est ce qui se passe juste après le saut, avant que le parachute ne s'ouvre.",
         "Si la force de l'air l'emportait, il **ralentirait**. Or sa vitesse ne change pas : les deux forces sont égales.",
         "Le poids agit toujours. Ce qui est nul, c'est leur **somme**, pas chacune d'elles."]}
 ]},

 {titre:"La deuxième loi : les forces changent la vitesse", blocs:[
  {t:"idee", x:"Quand la somme des forces n'est pas nulle, le vecteur vitesse change — et il change **dans la direction et le sens de cette somme**. C'est la deuxième loi de Newton, le principe le plus utile de toute la mécanique."},
  {t:"formule", titre:"Deuxième loi de Newton (version de Première)",
   x:"$Σ@v{F}$ et $Δ@v{v}$ ont **même direction et même sens**",
   note:"Plus précisément : $Σ@v{F} = m × @f{Δ@v{v}}{Δt}$. Une force plus grande, ou une masse plus petite, produit une variation de vitesse plus grande."},
  {t:"p", x:"Lis bien ce que dit cette loi, et surtout ce qu'elle ne dit pas. Elle ne dit **pas** que la force donne la direction du mouvement : elle dit qu'elle donne la direction du **changement** de mouvement. Une balle lancée vers le haut monte encore alors que son poids est déjà dirigé vers le bas — le poids ne la fait pas descendre immédiatement, il ralentit sa montée, puis inverse le mouvement."},
  {t:"tbl", head:["Situation","$Σ@v{F}$","Effet sur le vecteur vitesse"], rows:[
   ["Voiture qui démarre","Vers l'avant","Sa valeur augmente"],
   ["Voiture qui freine","Vers l'arrière","Sa valeur diminue"],
   ["Bille au bout d'une ficelle","Vers le centre","Sa direction tourne, sa valeur ne change pas"],
   ["Balle lancée en l'air","Vers le bas, toujours","Elle ralentit, s'arrête, puis redescend"]
  ]},
  {t:"astuce", titre:"Le raisonnement à double sens", x:"Cette loi se lit dans les deux sens, et c'est ce qui la rend si puissante. **Des forces vers les données** : je connais les forces, j'en déduis comment la vitesse va changer. **De la trajectoire vers les forces** : je vois une trajectoire courbée vers la gauche, j'en déduis qu'une force agit vers la gauche. C'est ainsi qu'on a découvert Neptune, à partir d'une trajectoire d'Uranus qui déviait."}
  ,{t:"methode", titre:"Utiliser la deuxième loi de Newton", etapes:[
   "**Repérer ce que l'énoncé donne** : les forces, ou bien la façon dont la vitesse change ? C'est ce qui décide du sens de lecture.",
   "**Si on donne les forces** : en faire la somme, et conclure que $Δ@v{v}$ a la même direction et le même sens. L'objet accélère, ralentit ou tourne selon la position de cette somme par rapport au mouvement.",
   "**Si on donne le mouvement** : construire $Δ@v{v}$, et conclure que la somme des forces pointe dans cette direction.",
   "**Pour un calcul de valeur** : $ΣF = m × @f{Δv}{Δt}$ — d'abord la variation de vitesse, puis sa valeur par seconde, puis la multiplication par la masse."
  ], exemple:"Un chariot de $2{,}0$ @u{kg} passe de $1{,}0$ à $5{,}0$ @u{m/s} en $2{,}0$ @u{s}. Alors $Δv = 4{,}0$ @u{m/s}, soit $2{,}0$ @u{m/s²}, et $ΣF = 2{,}0 × 2{,}0 = 4{,}0$ @u{N}."}
 ]},

 {titre:"Deux forces à distance : gravitation et électrostatique", blocs:[
  {t:"p", x:"Certaines forces agissent **sans contact**. Deux d'entre elles sont au programme, et leurs formules se ressemblent de façon frappante."},
  {t:"formule", titre:"Force d'interaction gravitationnelle",
   x:"$F = G × @f{m_A × m_B}{d^2}$",
   note:"$G = 6{,}67 × 10^{-11}$ @u{N·m²·kg⁻²} · masses en @u{kg} · $d$ en @u{m} · toujours **attractive**."},
  {t:"formule", titre:"Force d'interaction électrostatique (loi de Coulomb)",
   x:"$F = k × @f{|q_A × q_B|}{d^2}$",
   note:"$k = 9{,}0 × 10^{9}$ @u{N·m²·C⁻²} · charges en @u{C} · attractive si les charges sont de signes contraires, répulsive sinon."},
  {t:"p", x:"Les deux formules ont la même architecture : un produit des « quantités » en haut, le carré de la distance en bas. Cette dépendance en $@f{1}{d^2}$ a une conséquence marquante : **doubler la distance divise la force par quatre**, et non par deux. Tripler la distance la divise par neuf."},
  {t:"fig", titre:"Une force qui décroît en 1/d²",
   vue:[0,0,5.2,1.15], w:400, h:250, libre:true, grille:false, axes:false,
   objets:[
    {t:"axes", x0:0, y0:0, ax:"distance d", ay:"force F"},
    {t:"courbeXY", couleur:"bleu", pts:[[0.5,1.0],[0.7,0.51],[0.9,0.31],[1.1,0.21],[1.4,0.13],[1.8,0.077],[2.3,0.047],[3,0.028],[4,0.016],[5,0.010]]},
    {t:"seg", de:[1,0], a:[1,0.25], couleur:"line2", pointille:true},
    {t:"seg", de:[2,0], a:[2,0.0625], couleur:"line2", pointille:true},
    {t:"texte", x:1.05, y:0.35, txt:"d", couleur:"ink3"},
    {t:"texte", x:2.15, y:0.16, txt:"2d → F ÷ 4", couleur:"rouge", taille:12}
   ],
   note:"La force chute très vite avec la distance : c'est ce qui rend la gravitation négligeable dès qu'on s'éloigne un peu."},
  {t:"exemple", titre:"Exemple guidé — la force entre la Terre et la Lune", enonce:"Calculer la force gravitationnelle entre la Terre ($m_T = 6{,}0 × 10^{24}$ @u{kg}) et la Lune ($m_L = 7{,}3 × 10^{22}$ @u{kg}), distantes de $d = 3{,}8 × 10^{8}$ @u{m}.", etapes:[
   {q:"Écrire la formule", r:"$F = G × @f{m_T × m_L}{d^2}$, avec $G = 6{,}67 × 10^{-11}$."},
   {q:"Calculer le numérateur", r:"$m_T × m_L = 6{,}0 × 10^{24} × 7{,}3 × 10^{22} = 4{,}4 × 10^{47}$."},
   {q:"Calculer le dénominateur", r:"$d^2 = (3{,}8 × 10^{8})^2 = 1{,}4 × 10^{17}$. Attention : le carré porte sur le nombre **et** sur la puissance de dix."},
   {q:"Assembler", r:"$F = 6{,}67 × 10^{-11} × @f{4{,}4 × 10^{47}}{1{,}4 × 10^{17}} ≈ 2{,}1 × 10^{20}$ @u{N}."},
   {q:"Interpréter", r:"C'est cette force, et elle seule, qui maintient la Lune en orbite : elle courbe en permanence son vecteur vitesse vers la Terre."}
  ]},
  {t:"piege", titre:"Le carré au dénominateur", x:"Une erreur très fréquente : oublier de mettre la distance **au carré**, ou n'élever au carré que le nombre sans la puissance de dix. $(3 × 10^{8})^2 = 9 × 10^{16}$, et non $3 × 10^{16}$ ni $9 × 10^{8}$."}
 ]},

{titre:"Le principe des actions réciproques", blocs:[
  {t:"idee", x:"Une force n'existe jamais seule. Si un corps $@c{A}$ exerce une force sur un corps $@c{B}$, alors $@c{B}$ exerce **en même temps** sur $@c{A}$ une force de même valeur, de même direction, et de sens opposé. C'est la troisième loi de Newton."},
  {t:"p", x:"Deux patineuses face à face sur la glace : l'une pousse l'autre, et elles partent **toutes les deux** en arrière. Pourtant une seule a poussé. C'est que pousser, c'est aussi être poussé : le geste crée deux forces d'un coup, une sur chacune."},
  {t:"formule", titre:"Troisième loi de Newton",
   x:"$@v{F}_{A/B} = - @v{F}_{B/A}$",
   note:"Même valeur, même droite d'action, sens opposé. Et surtout : les deux forces s'exercent sur **deux objets différents**."},
  {t:"fig", titre:"Deux forces, deux objets",
   vue:[0,0,10,5], w:430, h:200, grille:false, axes:false,
   objets:[
    {t:"sol", de:0.6, a:9.4, y:1.2},
    {t:"rect", x:2, y:1.2, w:1.6, h:1.6, couleur:"bleu", nom:"A"},
    {t:"rect", x:6.4, y:1.2, w:1.6, h:1.6, couleur:"vert", nom:"B"},
    {t:"vec", de:[3.7,2.0], a:[6.3,2.0], couleur:"rouge", nom:"F A/B"},
    {t:"vec", de:[6.3,3.4], a:[3.7,3.4], couleur:"ambre", nom:"F B/A"},
    {t:"texte", x:5, y:0.25, txt:"deux corps distincts, une force sur chacun", couleur:"ink3", taille:11.5}
   ],
   note:"La flèche rouge s'applique à B, la flèche ambre à A. Elles ne se rencontrent jamais sur le même objet."},
  {t:"piege", titre:"Ces deux forces ne se compensent jamais", x:"C'est **le** piège de la mécanique. Deux forces ne peuvent se compenser que si elles s'exercent sur le **même** objet. Ici, l'une agit sur $@c{A}$, l'autre sur $@c{B}$ : elles appartiennent à deux bilans de forces différents, et n'ont aucune raison de s'annuler. Si elles se compensaient, rien ne pourrait jamais bouger."},
  {t:"p", x:"À ne pas confondre, donc, avec le poids et la réaction du support d'un livre posé sur une table : ces deux-là s'exercent bien sur **le même** livre, et se compensent. Le partenaire du poids du livre, c'est l'attraction que le livre exerce sur la Terre — une force qu'on ne voit jamais dessinée, et qui existe pourtant."},
  {t:"methode", titre:"Repérer une paire action–réaction", etapes:[
   "**Nommer les deux corps en présence**, et rien qu'eux : le pied et le sol, la roue et la route, la Terre et la pomme.",
   "**Écrire la première force en citant les deux** : $@v{F}_{pied/sol}$. Le premier nom est celui qui agit, le second celui qui subit.",
   "**Écrire la réciproque en inversant les deux noms** : $@v{F}_{sol/pied}$. C'est elle, la partenaire — aucune autre.",
   "**Vérifier qu'elles s'appliquent à deux objets différents.** Si les deux flèches partent du même objet, ce n'est pas une paire action–réaction.",
   "**Ne jamais les mettre dans le même bilan de forces** : chacune appartient à celui de l'objet qu'elle subit."
  ], exemple:"Pour marcher, le pied pousse le sol vers l'**arrière** ; le sol pousse alors le pied vers l'**avant**. C'est cette seconde force, et elle seule, qui fait avancer le marcheur — le sol nous propulse."},
  {t:"check", q:"Un cheval tire une charrette. La charrette tire le cheval en arrière avec exactement la même force. Comment l'attelage peut-il avancer ?",
   choix:["Ces deux forces s'exercent sur des objets différents : elles n'appartiennent pas au même bilan",
          "La force du cheval est en réalité un peu plus grande",
          "La force de la charrette n'existe pas vraiment",
          "L'attelage n'avance que si le sol est glissant"], bonne:0,
   expl:["Exact : la force du cheval agit sur la charrette, celle de la charrette agit sur le cheval. Pour savoir si le cheval avance, on ne regarde que le bilan **du cheval** — où figure aussi la poussée du sol sur ses sabots.",
         "Non : la troisième loi est une égalité exacte, sans exception. Ce n'est pas là qu'il faut chercher.",
         "Elle existe bel et bien, et le cheval la sent dans ses harnais. Elle ne s'applique simplement pas au même objet.",
         "C'est l'inverse : sans adhérence, le cheval patine sur place. C'est justement le sol qui, en le poussant vers l'avant, permet le mouvement."]}
 ]},
 {titre:"Récapitulatif : la méthode d'un exercice de mécanique", blocs:[
  {t:"liste", items:[
   "**1.** Choisir le système étudié (l'objet dont on parle) et le référentiel.",
   "**2.** Faire l'inventaire des forces : qui agit sur ce système ? Contact ou distance ?",
   "**3.** Les représenter par des vecteurs, à partir du centre de l'objet.",
   "**4.** Regarder si elles se compensent. Si oui, le vecteur vitesse ne change pas.",
   "**5.** Si non, la somme donne la direction et le sens de $Δ@v{v}$ — donc l'évolution du mouvement."
  ]},
  {t:"tbl", head:["La question ressemble à…","Ce qu'il faut faire"], rows:[
   ["« Calculer le poids »","$P = m × g$, la masse en @u{kg}"],
   ["« Le mouvement est rectiligne uniforme »","Conclure $Σ@v{F} = @v{0}$"],
   ["« Vers où pointe $Δ@v{v}$ ? »","Vers la somme des forces"],
   ["« Force gravitationnelle »","$G @f{m_A m_B}{d^2}$, distance **au carré**"],
   ["« Si la distance double »","La force est divisée par $4$"]
  ]},
  {t:"piege", titre:"Les erreurs les plus coûteuses", x:"**1.** Confondre masse ($@u{kg}$) et poids ($@u{N}$).<br>**2.** Croire que la force indique la direction du **mouvement** ; elle indique celle de son **changement**.<br>**3.** Oublier le carré de la distance dans les forces à distance."}
 ]}
],
exos:[
 {id:"fo1", niveau:1, type:"num", enonce:"Quelle est la valeur du poids d'un sac de $4{,}0$ @u{kg} sur Terre ? On prend $g = 9{,}81$ @u{N/kg}.",
  rep:39.24, tol:0.3, unite:"N",
  diag:[{v:4, m:"Tu as recopié la masse. La masse s'exprime en @u{kg}, le poids en @u{N} : ce sont deux grandeurs différentes, reliées par $P = m × g$."},
        {v:0.41, m:"Tu as divisé la masse par $g$ au lieu de multiplier. Le poids est plus grand que la masse en valeur numérique, puisque $g ≈ 10$."},
        {v:2.45, m:"Tu as calculé $@f{g}{m}$. La formule est $P = m × g$."}],
  corr:["**Ce que dit l'énoncé.** Une masse $m = 4{,}0$ @u{kg}, et $g = 9{,}81$ @u{N/kg}. On cherche la valeur du poids.",
        "**La différence à ne pas confondre.** La masse est une quantité de matière, en @u{kg} : elle ne change jamais. Le poids est une **force**, en @u{N} : c'est l'attraction exercée par l'astre, et elle dépend de l'astre.",
        "**La formule qui relie les deux.** $P = m × g$, où $g$ vaut $9{,}81$ @u{N/kg} sur Terre : chaque kilogramme y est tiré avec une force d'environ $9{,}81$ @u{N}.",
        "**Je remplace.** $P = 4{,}0 × 9{,}81$.",
        "**Je calcule.** $P ≈ 39{,}2$ @u{N}.",
        "**Je vérifie de tête.** Environ $10$ @u{N} par kilogramme : quatre kilos donnent à peu près $40$ @u{N}. Cohérent, et l'unité est bien le newton."],
  indice:"$P = m × g$, avec $g ≈ 9{,}81$ @u{N/kg}."},

 {id:"fo2", niveau:1, type:"qcm", enonce:"Un palet glisse en ligne droite à vitesse constante sur une patinoire. Que vaut la somme des forces qui s'exercent sur lui ?",
  choix:["Le vecteur nul","Un vecteur dirigé vers l'avant","Son poids","Un vecteur dirigé vers l'arrière"], bonne:0,
  diag:["",
        "Une force vers l'avant le ferait **accélérer**. Or sa vitesse ne change pas.",
        "Le poids s'exerce bien, mais la glace le compense exactement par sa réaction. C'est la **somme** qui est nulle, pas chaque force.",
        "Une force vers l'arrière le ferait ralentir. C'est ce qui arrive en réalité avec les frottements — mais l'énoncé précise une vitesse constante."],
  corr:["**Ce que dit l'énoncé.** Un palet glisse **en ligne droite à vitesse constante** sur une patinoire. On cherche la somme des forces.",
        "**Je traduis l'énoncé en termes de vecteur vitesse.** Ligne droite = direction constante. Vitesse constante = valeur constante. Le vecteur vitesse ne change donc pas du tout.",
        "**J'en déduis sa variation.** $Δ@v{v} = @v{0}$.",
        "**J'applique le principe d'inertie.** Si le vecteur vitesse ne change pas, la somme des forces est nulle. Et réciproquement.",
        "**Je conclus.** $Σ@v{F} = @v{0}$.",
        "**Attention à ne pas surinterpréter.** Cela ne signifie pas qu'aucune force n'agit : le poids tire vers le bas, la glace pousse vers le haut. C'est leur **somme** qui est nulle, parce qu'elles se compensent exactement."],
  indice:"Principe d'inertie : vitesse constante en ligne droite signifie forces compensées."},

 {id:"fo3", niveau:2, type:"qcm", enonce:"Une balle est lancée verticalement vers le haut. Pendant sa montée, quelle est la direction de la somme des forces (on néglige l'air) ?",
  choix:["Vers le bas","Vers le haut, comme le mouvement","Nulle, car elle monte à vitesse constante","Elle change de sens au sommet"], bonne:0,
  diag:["",
        "C'est l'erreur la plus répandue en mécanique. La force n'indique pas le sens du **mouvement**, mais celui de son **changement**. La balle monte tout en ralentissant : la force est donc dirigée vers le bas.",
        "La balle ralentit pendant sa montée : sa vitesse n'est pas constante. La somme des forces n'est donc pas nulle.",
        "Le poids garde exactement la même direction et le même sens pendant tout le trajet, montée comprise. Rien ne change au sommet, sinon le sens du mouvement."],
  corr:["**Ce que dit l'énoncé.** Une balle est lancée verticalement vers le haut, l'air est négligé. On cherche la direction de la somme des forces **pendant la montée**.",
        "**Étape 1 — l'inventaire des forces.** Une fois la balle lâchée, la main n'agit plus. L'air est négligé. Il ne reste que le **poids**.",
        "**Étape 2 — la direction du poids.** Verticale, vers le bas. Toujours, partout, pendant tout le vol : à la montée, au sommet, à la descente.",
        "**Étape 3 — le piège à éviter.** La deuxième loi ne dit pas que la force donne la direction du **mouvement**, mais celle de son **changement**. La balle monte tout en ralentissant.",
        "**Étape 4 — je vérifie la cohérence.** Une force opposée au mouvement freine : c'est bien ce qu'on observe, la balle ralentit jusqu'à s'arrêter.",
        "**Je conclus.** La somme des forces est dirigée **vers le bas**, pendant toute la montée. Au sommet la vitesse s'annule, puis le poids — inchangé — fait redescendre la balle en l'accélérant."],
  indice:"Sépare bien le sens du mouvement et le sens de son changement."},

 {id:"fo4", niveau:2, type:"num", enonce:"Sur la Lune, $g_L = 1{,}6$ @u{N/kg}. Quel est le poids d'une combinaison de $12$ @u{kg} sur la Lune ?",
  rep:19.2, tol:0.2, unite:"N",
  diag:[{v:117.7, m:"Tu as utilisé le $g$ terrestre ($9{,}81$). L'énoncé donne celui de la Lune : $1{,}6$ @u{N/kg}."},
        {v:12, m:"Tu as recopié la masse. La masse est la même partout ; c'est le poids qui change d'un astre à l'autre."},
        {v:7.5, m:"Tu as divisé la masse par $g_L$ au lieu de multiplier."}],
  corr:["**Ce que dit l'énoncé.** Une combinaison de $12$ @u{kg}, sur la Lune où $g_L = 1{,}6$ @u{N/kg}.",
        "**Ce qui change d'un astre à l'autre.** La masse ne change pas : $12$ @u{kg} sur Terre, $12$ @u{kg} sur la Lune. C'est $g$ qui change, parce que la Lune est bien moins massive que la Terre.",
        "**La formule reste la même.** $P = m × g$, avec le $g$ de l'astre concerné.",
        "**Je remplace avec le bon $g$.** $P = 12 × 1{,}6$.",
        "**Je calcule.** $P = 19{,}2$ @u{N}.",
        "**Je compare avec la Terre.** Sur Terre, la même combinaison pèserait $12 × 9{,}81 ≈ 118$ @u{N}, soit six fois plus. C'est exactement pour cela que les astronautes s'y déplacent par bonds — sans que leur masse ait changé d'un gramme."],
  indice:"Même formule, mais avec le $g$ de l'astre concerné."},

 {id:"fo5", niveau:2, type:"qcm", enonce:"Si la distance entre deux corps est multipliée par 3, par combien la force gravitationnelle est-elle divisée ?",
  choix:["9","3","6","27"], bonne:0,
  diag:["",
        "La distance intervient **au carré** au dénominateur. Une distance triplée donne donc $3^2 = 9$ au dénominateur, pas 3.",
        "6 correspondrait à $3 × 2$, un raisonnement qui mélange le facteur et l'exposant. Le carré de 3 vaut 9.",
        "27 serait le cube de 3. La loi de gravitation fait intervenir le carré de la distance, pas son cube."],
  corr:["**Ce que dit l'énoncé.** La distance entre deux corps est multipliée par $3$. On cherche par combien la force gravitationnelle est divisée.",
        "**J'écris la loi.** $F = G × @f{m_A m_B}{d^2}$. Les masses ne changent pas ; seule la distance varie.",
        "**Où se trouve la distance ?** Au **dénominateur**, et **au carré**. C'est ce carré qui fait toute la réponse.",
        "**J'applique le facteur.** Si $d$ devient $3d$, alors $d^2$ devient $(3d)^2 = 9 d^2$. Le dénominateur est multiplié par $9$, pas par $3$.",
        "**J'en déduis la force.** Un dénominateur $9$ fois plus grand donne une force $9$ fois plus petite.",
        "**Je conclus, et je retiens la règle.** La force est divisée par $9$. Doubler la distance divise par $4$, la tripler divise par $9$ : c'est ce qui rend la gravitation négligeable dès qu'on s'éloigne un peu."],
  indice:"La distance est au carré : un facteur 3 sur $d$ devient un facteur $3^2$ sur $d^2$."},

 {id:"fo6", niveau:3, type:"num", enonce:"Deux charges de $q_A = 2{,}0 × 10^{-6}$ @u{C} et $q_B = 3{,}0 × 10^{-6}$ @u{C} sont distantes de $d = 0{,}30$ @u{m}. Quelle est la valeur de la force électrostatique, en @u{N} ? On prend $k = 9{,}0 × 10^{9}$ @u{N·m²·C⁻²}.",
  rep:0.6, tol:0.01, unite:"N",
  diag:[{v:1.8, m:"Tu as oublié d'élever la distance au carré : tu as divisé par $0{,}30$ au lieu de $0{,}090$."},
        {v:0.054, m:"Tu as multiplié par $d^2$ au lieu de diviser. La distance est au **dénominateur** : plus les charges sont éloignées, plus la force est faible."},
        {v:6, m:"Une erreur d'un facteur 10 s'est glissée dans les puissances de dix. Reprends : $2{,}0×10^{-6} × 3{,}0×10^{-6} = 6{,}0×10^{-12}$."}],
  corr:["**Ce que dit l'énoncé.** Deux charges, $q_A = 2{,}0 × 10^{-6}$ @u{C} et $q_B = 3{,}0 × 10^{-6}$ @u{C}, distantes de $d = 0{,}30$ @u{m}, avec $k = 9{,}0 × 10^{9}$.",
        "**La loi à utiliser.** La loi de Coulomb : $F = k × @f{|q_A × q_B|}{d^2}$. Même architecture que la gravitation : un produit en haut, le carré de la distance en bas.",
        "**Étape 1 — le numérateur.** $q_A × q_B = 2{,}0×10^{-6} × 3{,}0×10^{-6}$. Je multiplie les nombres : $2 × 3 = 6$. J'additionne les exposants : $-6 + (-6) = -12$. Donc $6{,}0 × 10^{-12}$.",
        "**Étape 2 — le dénominateur.** $d^2 = 0{,}30^2 = 0{,}090$ @u{m²}. Attention : $0{,}30$ au carré ne fait pas $0{,}60$ mais $0{,}09$.",
        "**Étape 3 — j'assemble.** $F = 9{,}0×10^{9} × @f{6{,}0×10^{-12}}{0{,}090}$. La fraction vaut $6{,}67×10^{-11}$, et en multipliant : $F = 0{,}60$ @u{N}.",
        "**Je vérifie.** Moins d'un newton pour des charges de quelques microcoulombs à $30$ @u{cm} : plausible. Oublier le carré aurait donné $1{,}8$ @u{N}, trois fois trop."],
  indice:"N'oublie pas d'élever la distance au carré avant de diviser."},

 {id:"fo7", niveau:3, type:"txt", enonce:"Une bille tourne à vitesse constante au bout d'une ficelle. Vers où pointe la somme des forces ? (deux mots)",
  reps:["vers le centre","le centre","centre du cercle","vers le centre du cercle"],
  diag:[{r:"vers l avant", m:"Vers l'avant, la bille irait de plus en plus vite. Or sa vitesse garde la même valeur : ce qui change, c'est sa direction."},
        {r:"vers l exterieur", m:"Si la somme des forces pointait vers l'extérieur, la bille s'éloignerait et quitterait le cercle. C'est la ficelle qui la retient — donc qui tire vers l'intérieur."},
        {r:"nulle", m:"Si elle était nulle, la bille irait en ligne droite d'après le principe d'inertie. Or sa trajectoire est un cercle : quelque chose la fait tourner en permanence."}],
  corr:["**Ce que dit l'énoncé.** Une bille tourne à vitesse constante au bout d'une ficelle. On cherche la direction de la somme des forces.",
        "**Le raisonnement à suivre.** Je ne connais pas les forces, mais je connais le mouvement. Je lis donc la deuxième loi **à l'envers** : du mouvement vers les forces.",
        "**Étape 1 — le vecteur vitesse change-t-il ?** Sa valeur, non. Sa direction, oui : elle tourne en permanence pour rester tangente au cercle. Donc le vecteur change, et $Δ@v{v}$ n'est pas nul.",
        "**Étape 2 — je construis $Δ@v{v}$.** Deux vecteurs de même longueur, légèrement pivotés, reportés d'un même point : la flèche qui joint leurs pointes est dirigée vers l'intérieur du cercle.",
        "**Étape 3 — j'applique la deuxième loi.** $Σ@v{F}$ a exactement la même direction et le même sens que $Δ@v{v}$ : elle pointe **vers le centre**.",
        "**Je vérifie physiquement.** C'est la ficelle qui tire la bille vers la main. Si on la coupe, plus rien ne la retient : elle part en ligne droite, selon la tangente. Ce qui confirme que la force allait bien vers le centre."],
  indice:"Construis $Δ@v{v}$ : la somme des forces pointe dans la même direction."},

 {id:"fo8", niveau:3, type:"num", enonce:"Un chariot de masse $m = 2{,}0$ @u{kg} voit sa vitesse passer de $1{,}0$ à $5{,}0$ @u{m/s} en $2{,}0$ @u{s}, en ligne droite. Quelle est la valeur de la somme des forces, en @u{N} ?",
  rep:4, tol:0.05, unite:"N",
  diag:[{v:2, m:"Tu as calculé la variation de vitesse par seconde ($2{,}0$ @u{m/s²}) mais oublié de multiplier par la masse. La loi est $ΣF = m × @f{Δv}{Δt}$."},
        {v:8, m:"Tu as multiplié par la variation totale de vitesse sans diviser par la durée : $2{,}0 × 4{,}0 = 8$. La durée de $2{,}0$ @u{s} doit intervenir."},
        {v:10, m:"Tu as utilisé la vitesse finale au lieu de la variation. C'est le **changement** de vitesse qui compte, pas sa valeur."}],
  corr:["**Ce que dit l'énoncé.** $m = 2{,}0$ @u{kg}, vitesse de $1{,}0$ à $5{,}0$ @u{m/s} en $2{,}0$ @u{s}, en ligne droite.",
        "**La loi à utiliser.** La deuxième loi de Newton, sous sa forme chiffrée : $ΣF = m × @f{Δv}{Δt}$.",
        "**Étape 1 — la variation de vitesse.** $Δv = 5{,}0 - 1{,}0 = 4{,}0$ @u{m/s}. C'est un **écart**, pas la vitesse finale.",
        "**Étape 2 — la variation par seconde.** $@f{Δv}{Δt} = @f{4{,}0}{2{,}0} = 2{,}0$ @u{m/s²}. La vitesse gagne $2$ @u{m/s} chaque seconde.",
        "**Étape 3 — je multiplie par la masse.** $ΣF = 2{,}0 × 2{,}0 = 4{,}0$ @u{N}.",
        "**Je vérifie le rôle de la masse.** À variation de vitesse égale, un chariot deux fois plus lourd demanderait une force deux fois plus grande. C'est bien ce que dit la formule : la masse mesure la résistance au changement de mouvement."],
  indice:"Trois temps : la variation de vitesse, sa valeur par seconde, puis la multiplication par la masse."},

{id:"fo9", niveau:1, type:"qcm", enonce:"Parmi ces forces, laquelle n'est **pas** une force de contact ?",
  choix:["Le poids","La tension d'un fil","La réaction du sol","Le frottement de l'air"], bonne:0,
  diag:["",
        "Un fil doit être attaché à l'objet pour le tirer : il y a bien contact.",
        "Le sol doit toucher l'objet pour le porter : c'est une force de contact.",
        "L'air touche l'objet en mouvement sur toute sa surface : c'est un contact, même s'il est diffus."],
  corr:["**La distinction à faire.** Une force de **contact** exige que les deux corps se touchent. Une force **à distance** agit à travers le vide.",
        "**Je teste la tension d'un fil.** Sans fil attaché, pas de tension : c'est un contact.",
        "**Je teste la réaction du sol.** Elle n'existe que si l'objet repose sur le sol : contact.",
        "**Je teste le frottement de l'air.** L'air frotte la surface de l'objet : contact également, même si l'on n'y pense pas toujours.",
        "**Je teste le poids.** La Terre attire la pomme sans la toucher, à travers des kilomètres d'air ou même de vide.",
        "**Je conclus.** Le poids est une force **à distance**, comme la gravitation et l'attraction électrique. C'est la seule de la liste."],
  indice:"Demande-toi, pour chacune : les deux corps ont-ils besoin de se toucher ?"},

 {id:"fo10", niveau:2, type:"num", enonce:"Un rover de masse $350$ @u{kg} est posé sur Mars, où $g_M = 3{,}7$ @u{N/kg}. Quelle est la valeur de son poids, en @u{N} ?",
  rep:1295, tol:5, unite:"N",
  diag:[{v:3434, m:"Tu as utilisé le $g$ terrestre ($9{,}81$). Sur Mars, il ne vaut que $3{,}7$ @u{N/kg} : la planète est bien moins massive."},
        {v:350, m:"Tu as recopié la masse. Elle est la même partout dans l'univers ; c'est le poids qui change d'un astre à l'autre."},
        {v:94.6, m:"Tu as divisé la masse par $g$ au lieu de multiplier."}],
  corr:["**Ce que dit l'énoncé.** Une masse en kilogrammes, et l'intensité de la pesanteur **sur Mars**.",
        "**La formule.** $P = m × g$, avec le $g$ de l'astre où se trouve l'objet.",
        "**Ce qui change, ce qui ne change pas.** La masse du rover est la même sur Terre et sur Mars : $350$ @u{kg}. Seul $g$ change.",
        "**Je remplace.** $P = 350 × 3{,}7$.",
        "**Je calcule.** $P ≈ 1295$ @u{N}.",
        "**Je compare.** Sur Terre, le même rover pèserait $350 × 9{,}81 ≈ 3434$ @u{N}, soit presque trois fois plus. C'est pourquoi un engin conçu pour Mars peut être plus léger — mais sa masse, elle, reste à transporter jusque là-bas."],
  indice:"$P = m × g$, avec le $g$ de Mars et non celui de la Terre."},

 {id:"fo11", niveau:2, type:"num", enonce:"Deux charges exercent l'une sur l'autre une force de $0{,}60$ @u{N}. On **double** la distance qui les sépare, sans rien changer d'autre. Que vaut la nouvelle force, en @u{N} ?",
  rep:0.15, tol:0.005, unite:"N",
  diag:[{v:0.3, m:"Tu as divisé par $2$. Mais la distance intervient **au carré** : doubler $d$ multiplie $d^2$ par $4$, donc divise la force par $4$."},
        {v:1.2, m:"Tu as multiplié par $2$. Éloigner les charges **diminue** la force, cela ne l'augmente pas."},
        {v:2.4, m:"Tu as multiplié par $4$ au lieu de diviser. La distance est au **dénominateur** : plus elle est grande, plus la force est faible."}],
  corr:["**La loi en jeu.** La loi de Coulomb : $F = k @f{|q_A q_B|}{d^2}$. Les charges ne changent pas, seule la distance varie.",
        "**Où se trouve la distance.** Au dénominateur, et **au carré**. C'est ce carré qui fait toute la réponse.",
        "**J'applique le facteur.** Si $d$ devient $2d$, alors $d^2$ devient $(2d)^2 = 4 d^2$.",
        "**J'en déduis l'effet sur la force.** Un dénominateur $4$ fois plus grand donne une force $4$ fois plus petite.",
        "**Je calcule.** $F = @f{0{,}60}{4} = 0{,}15$ @u{N}.",
        "**La règle à retenir.** Distance $×2$ → force $÷4$. Distance $×3$ → force $÷9$. C'est ce qui rend ces forces négligeables dès qu'on s'éloigne un peu."],
  indice:"Doubler la distance ne divise pas la force par 2 : regarde la puissance à laquelle $d$ apparaît."},

 {id:"fo12", niveau:3, type:"num", enonce:"Un satellite de $800$ @u{kg} orbite à $7{,}0 × 10^{6}$ @u{m} du centre de la Terre ($m_T = 6{,}0 × 10^{24}$ @u{kg}). Quelle est la valeur de la force gravitationnelle, en @u{N} ? On donne $G = 6{,}67 × 10^{-11}$.",
  rep:6534, tol:80, unite:"N",
  diag:[{v:45715, m:"Tu as oublié d'élever la distance au carré : tu as divisé par $7{,}0 × 10^{6}$ au lieu de $4{,}9 × 10^{13}$."},
        {v:7848, m:"Tu as calculé le poids au sol ($800 × 9{,}81$). À $7000$ @u{km} du centre, la Terre attire moins fort."},
        {v:800, m:"Tu as recopié la masse du satellite. La question porte sur une force, en newtons."}],
  corr:["**La loi en jeu.** $F = G × @f{m_T × m_s}{d^2}$, avec toutes les grandeurs en unités du système.",
        "**Le numérateur, étape par étape.** $m_T × m_s = 6{,}0 × 10^{24} × 800 = 4{,}8 × 10^{27}$.",
        "**Je multiplie par $G$.** $6{,}67 × 10^{-11} × 4{,}8 × 10^{27} = 3{,}20 × 10^{17}$. J'additionne les exposants : $-11 + 27 = 16$, et $6{,}67 × 4{,}8 = 32$, soit $32 × 10^{16} = 3{,}20 × 10^{17}$.",
        "**Le dénominateur.** $d^2 = (7{,}0 × 10^{6})^2 = 49 × 10^{12} = 4{,}9 × 10^{13}$. Le carré porte sur le nombre **et** sur la puissance de dix.",
        "**Je divise.** $F = @f{3{,}20 × 10^{17}}{4{,}9 × 10^{13}} ≈ 6{,}5 × 10^{3}$ @u{N}.",
        "**J'interprète.** Environ $6500$ @u{N} : c'est cette force, et elle seule, qui courbe en permanence la trajectoire du satellite et le maintient en orbite au lieu de le laisser filer tout droit."],
  indice:"Traite le numérateur et le dénominateur séparément, et n'oublie pas le carré sur la puissance de dix."},

{id:"fo13", niveau:2, type:"qcm", enonce:"Un livre est posé sur une table. Quelle est la force **réciproque** du poids du livre ?",
  choix:["L'attraction que le livre exerce sur la Terre",
         "La réaction de la table sur le livre",
         "Le poids de la table",
         "La force de frottement entre le livre et la table"], bonne:0,
  diag:["",
        "C'est la confusion la plus fréquente. La réaction de la table s'exerce sur le **même** objet que le poids — le livre — et c'est pour cela qu'elles se compensent. Une paire action–réaction, elle, se répartit sur deux objets.",
        "Le poids de la table est l'attraction exercée par la Terre sur la table : une autre force, qui concerne un autre objet.",
        "Le frottement s'exerce lui aussi sur le livre, et il est horizontal. Rien à voir avec le poids."],
  corr:["**Ce que dit l'énoncé.** Le poids du livre, c'est-à-dire la force exercée par la **Terre** sur le **livre**.",
        "**La règle de la troisième loi.** La force réciproque s'obtient en **inversant les deux noms** : si la Terre agit sur le livre, alors le livre agit sur la Terre.",
        "**J'écris la paire.** $@v{F}_{Terre/livre}$ et $@v{F}_{livre/Terre}$. Même valeur, sens opposé.",
        "**Je vérifie le critère décisif.** Ces deux forces s'appliquent bien à **deux objets différents** : l'une au livre, l'autre à la Terre.",
        "**J'écarte la réaction de la table.** Elle s'exerce sur le livre, comme le poids : deux forces sur le même objet, qui se compensent. Ce n'est pas une paire action–réaction.",
        "**Ce que cela signifie.** Le livre attire vraiment la Terre, avec exactement la même force que la Terre l'attire. On ne le voit pas parce que la Terre est colossalement plus massive : la même force ne lui donne aucune variation de vitesse mesurable."],
  indice:"Inverse les deux noms de la force de départ : « la Terre agit sur le livre » devient…"},

 {id:"fo14", niveau:3, type:"num", enonce:"Une fusée éjecte ses gaz vers l'arrière avec une force de $2{,}4 × 10^{6}$ @u{N}. Quelle est la valeur de la force que les gaz exercent en retour sur la fusée, en @u{N} ?",
  rep:2.4e6, tol:1e4, unite:"N",
  diag:[{v:0, m:"Une force réciproque n'est jamais nulle. Si elle l'était, aucune fusée ne pourrait décoller — et c'est pourtant ainsi qu'elles avancent, y compris dans le vide où il n'y a rien contre quoi s'appuyer."},
        {v:1.2e6, m:"Tu as divisé par deux, comme si la force se partageait entre les deux corps. La troisième loi dit une **égalité** : chacun reçoit la force entière."},
        {v:4.8e6, m:"Tu as doublé. Les deux forces sont de même valeur, elles ne s'additionnent pas."}],
  corr:["**Ce que dit l'énoncé.** La fusée exerce sur les gaz une force de $2{,}4 × 10^{6}$ @u{N}, dirigée vers l'arrière.",
        "**La loi à appliquer.** Troisième loi de Newton : $@v{F}_{A/B} = - @v{F}_{B/A}$. Même valeur, sens opposé.",
        "**J'inverse les deux noms.** La fusée agit sur les gaz, donc les gaz agissent sur la fusée.",
        "**Je conclus sur la valeur.** Elle est identique : $2{,}4 × 10^{6}$ @u{N}. Seul le sens change — cette force-là est dirigée vers l'**avant**.",
        "**Je vérifie les objets.** L'une s'applique aux gaz, l'autre à la fusée : deux corps différents, comme il se doit.",
        "**Ce que cela explique.** C'est cette force vers l'avant, et elle seule, qui propulse la fusée. Elle n'a besoin de rien pour s'appuyer : c'est pour cela qu'une fusée fonctionne dans le vide, contrairement à ce qu'on imagine souvent."],
  indice:"La troisième loi énonce une égalité de valeurs : seule l'orientation change."},

 {id:"fo15", niveau:3, type:"num", unite:"N",
  enonce:"Le schéma ci-dessous représente les quatre forces qui s'exercent sur une caisse tirée sur le sol. Quelle est la valeur de la somme des forces ?",
  fig:{titre:"Document — bilan des forces sur la caisse", vue:[0,0,10,4.9], w:420, h:235,
       libre:true, grille:false, axes:false, objets:[
    {t:"sol", de:0.6, a:9.4, y:1.6, couleur:"ink3"},
    {t:"rect", x:4.4, y:1.6, w:1.2, h:1.5, couleur:"bleu"},
    {t:"vec", de:[5,2.35], a:[5,0.5], couleur:"ambre"},
    {t:"texte", x:5.9, y:0.85, txt:"P = 300 N", couleur:"ambre", taille:12},
    {t:"vec", de:[5,2.35], a:[5,4.2], couleur:"vert"},
    {t:"texte", x:5.9, y:4.05, txt:"R = 300 N", couleur:"vert", taille:12},
    {t:"vec", de:[5,2.35], a:[8.4,2.35], couleur:"bleu"},
    {t:"texte", x:8.2, y:3.05, txt:"F = 80 N", couleur:"bleu", taille:12},
    {t:"vec", de:[5,2.35], a:[3.7,2.35], couleur:"rouge"},
    {t:"texte", x:3.15, y:3.05, txt:"f = 30 N", couleur:"rouge", taille:12}
   ], note:"Deux forces verticales, deux forces horizontales. Les valeurs sont écrites à côté de chaque flèche."},
  rep:50, tol:0.5,
  diag:[{v:0, m:"Les forces verticales se compensent, oui — mais pas les horizontales : $80$ @u{N} contre $30$ @u{N}. La somme n'est donc pas nulle."},
        {v:110, m:"Tu as additionné $80$ et $30$. Ces deux forces sont de sens **opposés** : elles se retranchent."},
        {v:710, m:"Tu as additionné les quatre valeurs. Une somme de forces n'est pas une somme de nombres : il faut tenir compte des directions et des sens."},
        {v:600, m:"Tu as additionné le poids et la réaction. Ces deux-là sont opposées et de même valeur : leur somme est nulle."}],
  corr:["**Ce que montre le document.** Quatre flèches partent du centre de la caisse. Deux sont verticales — le poids vers le bas, la réaction du sol vers le haut. Deux sont horizontales — la traction vers la droite, le frottement vers la gauche.",
        "**Le réflexe : séparer les directions.** On ne peut jamais additionner des forces de directions différentes comme des nombres. On traite d'abord la verticale, puis l'horizontale.",
        "**Étape 1 — la verticale.** $P = 300$ @u{N} vers le bas, $R = 300$ @u{N} vers le haut. Mêmes valeurs, sens opposés : elles se **compensent** exactement. Leur somme est nulle. C'est cohérent avec le fait que la caisse ne s'enfonce ni ne décolle.",
        "**Étape 2 — l'horizontale.** $F = 80$ @u{N} vers la droite, $f = 30$ @u{N} vers la gauche. Sens opposés, valeurs différentes : on **soustrait**. $80 - 30 = 50$ @u{N}, orientés vers la droite, du côté de la plus grande.",
        "**Étape 3 — je rassemble.** La somme des forces vaut $0$ à la verticale et $50$ @u{N} à l'horizontale : au total, $50$ @u{N} dirigés vers la droite.",
        "**Ce que cela m'apprend sur le mouvement.** La somme des forces n'est pas nulle : d'après le principe d'inertie, la caisse ne peut donc pas aller à vitesse constante. Elle **accélère vers la droite**, dans le sens de cette résultante. Si l'on augmentait le frottement jusqu'à $80$ @u{N}, la somme deviendrait nulle et le mouvement se stabiliserait."],
  indice:"Traite d'abord les deux forces verticales, puis les deux horizontales. Deux forces opposées se retranchent."}
]
}

]);
